"use client";

import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import {
  Accordion,
  AccordionItem,
  Button,
  ComposedModal,
  Header,
  HeaderGlobalAction,
  HeaderGlobalBar,
  HeaderMenuButton,
  HeaderName,
  InlineNotification,
  ModalBody,
  ModalFooter,
  ModalHeader,
  ProgressBar,
  Select,
  SelectItem,
  SideNav,
  SideNavItems,
  SideNavLink,
  SkeletonText,
  SkipToContent,
  Tag,
  TextArea,
  TextInput,
  Theme,
} from "@carbon/react";
import {
  Add,
  Analytics,
  ArrowRight,
  Asleep,
  Calendar,
  Chat,
  Checkmark,
  Close,
  Dashboard,
  Document,
  Watson,
  Launch,
  Menu,
  Renew,
  Search,
  Settings,
  UserAvatar,
  WatsonHealthTextAnnotationToggle,
} from "@carbon/icons-react";
import { CarbonCapabilityChart } from "./CarbonVisuals";
import RelationshipGraph, { type AccountRelationship as GraphRelationship, type GraphPosition, type RelationshipGraphMode } from "./RelationshipGraph";
import { HypothesisConfidenceChart, PortfolioBubbleChart, StakeholderCoverageChart } from "./V5Charts";

type Priority = "Alta" | "Média" | "Baixa";
type Evidence = { sourceType: string; sourceId: string; title: string; excerpt: string; occurredAt: string };
type Score = { name: string; short: string; alignment: number; value: number; readiness: number; confidence: number; level: Priority; evidence: string[]; action: string };
type Insight = { summary: string; signals: string[]; ibmThemes: string[]; nextQuestions: string[]; nextActions: string[]; risks: string[]; stakeholders: string[]; systems: string[]; painPoints: string[]; aiStatus: string };
type Meeting = { id: string; discoveryId: string; title: string; notes: string; summary: string; insights: Insight; aiStatus: string; createdAt: string; scheduledAt?: string | null; attendees?: string[]; objective?: string; preparation?: Record<string, unknown>; meetingStatus?: string };
type Stakeholder = { id: string; discoveryId: string; name: string; role: string; area: string; reportsToId: string | null; influence: string; stance: string; priorities: string[]; notes: string; source: "manual" | "suggested"; createdAt: string; updatedAt: string };
type Discovery = { id: string; customerName: string; industry: string; companySize: string; owner: string; visibility: string; dataClassification: "test" | "confidential"; companyDomain: string | null; stage: string; progress: number; priority: Priority; challengeSummary: string; answers: Array<{ key: string; question: string; answer: string; at: string }>; meetings: Meeting[]; scores: Score[]; recommendations: Array<{ type: string; name: string; rationale: string }>; nextEngagement: string; updatedAt: string };
type AccountEvent = { id: string; discoveryId: string; type: string; title: string; content: string; sourceType: string; sourceId: string | null; evidenceStatus: "confirmed" | "assumption" | "gap" | "stale"; confidence: number; occurredAt: string };
type Memory = { discoveryId: string; executiveSummary: string; known: string[]; assumptions: string[]; gaps: string[]; changes: string[]; aiStatus: string; version: number; updatedAt: string };
type Conversation = { stakeholder?: string; theme?: string; opener?: string; questions?: string[]; objection?: string; successCriterion?: string };
type Action = { id: string; discoveryId: string; stakeholderId: string | null; type: string; title: string; rationale: string; whyNow: string; nextStep: string; impact: number; urgency: number; confidence: number; maturity: number; effort: number; priorityScore: number; status: string; dueAt: string | null; expectedOutcome: string; conversation: Conversation; snoozedUntil: string | null; feedbackReason: string | null; rankAdjustment: number; evidence: Evidence[] };
type Hypothesis = { id: string; discoveryId: string; capabilityKey: string; title: string; problem: string; products: string[]; stakeholderIds: string[]; evidence: Evidence[]; gaps: string[]; confidence: number; stage: string; nextStep: string };
type Plan = { discoveryId: string; priorities: string[]; initiatives: string[]; objectives: string[]; risks: string[]; ecosystem: string[]; relationship: string[]; plan30: string[]; plan60: string[]; plan90: string[]; approvalStatus: string; suggestion: Record<string, string[]>; updatedAt: string };
type AccountDocument = { id: string; discoveryId: string; name: string; contentType: string; sizeBytes: number; status: string; summary: string; createdAt: string };
type Relationship = { id: string; discoveryId: string; sourceStakeholderId: string; targetStakeholderId: string; relationType: string; label: string; confidence: number; evidence: Evidence[]; status: string };
type GraphLayout = { id: string; discoveryId: string; mode: RelationshipGraphMode; nodes: Array<{ id: string; x: number; y: number }>; viewport: Record<string, number> };
type ExternalSignal = { id: string; discoveryId: string; title: string; summary: string; sourceUrl: string; publisher: string; publishedAt: string | null; status: string; confidence: number; createdAt: string };
type Snapshot = { id: string; discoveryId: string; reason: string; snapshot: { hypothesisConfidence?: Array<{ key: string; confidence: number }> }; confidence: number; createdAt: string };
type AIRun = { id: string; discoveryId: string; agent: string; provider: string; model?: string; status: string; confidence: number; detail: string; promptTokens?: number; outputTokens?: number; latencyMs?: number; cached?: boolean; errorCode?: string | null; createdAt: string };
type ApiData = { discoveries: Discovery[]; meetings: Meeting[]; stakeholders: Stakeholder[]; events: Array<{ id: string; discoveryId: string; type: string; detail: string; createdAt: string }>; accountEvents: AccountEvent[]; memories: Memory[]; actions: Action[]; hypotheses: Hypothesis[]; plans: Plan[]; documents: AccountDocument[]; chats: unknown[]; aiRuns: AIRun[]; relationships: Relationship[]; graphLayouts: GraphLayout[]; externalSignals: ExternalSignal[]; snapshots: Snapshot[]; actionFeedback: unknown[] };
type Briefing = { headline: string; summary: string; focusAccounts: Array<{ accountId: string; accountName: string; headline: string; whyNow: string; priority: number; suggestedAction: string; citationIds: string[] }>; changes: string[]; meetingsToPrepare: string[]; overdueCommitments: string[] };
type AIStatus = { mode: string; provider: string; watsonx: { configured: boolean; model: string | null }; gemini: { configured: boolean; model: string; embeddingModel: string; limits: Record<string, number>; usage?: Record<string, number | boolean>; remaining?: Record<string, number> }; fallback: { available: boolean } };
type ChatResult = { answer: string; citations: Evidence[]; confidence: number; aiStatus: string; suggestedActions: string[]; provider?: string; model?: string | null; cached?: boolean; facts?: string[]; hypotheses?: string[]; inferences?: string[] };
type BriefingResponse = { briefing?: Briefing; provider?: string; model?: string | null; cached?: boolean; error?: string };

const emptyData: ApiData = { discoveries: [], meetings: [], stakeholders: [], events: [], accountEvents: [], memories: [], actions: [], hypotheses: [], plans: [], documents: [], chats: [], aiRuns: [], relationships: [], graphLayouts: [], externalSignals: [], snapshots: [], actionFeedback: [] };
const nav = [{ id: "home", label: "Início", icon: Dashboard }, { id: "accounts", label: "Inteligência de contas", icon: Document }, { id: "radar", label: "Radar da carteira", icon: Analytics }, { id: "settings", label: "Configurações", icon: Settings }] as const;
const accountModes = [{ id: "overview", label: "Visão geral" }, { id: "activity", label: "Atividade" }, { id: "relationships", label: "Relacionamentos" }, { id: "strategy", label: "Estratégia" }] as const;
const questions = ["O que sabemos sobre a estratégia de cloud?", "Quem pode patrocinar uma conversa de FinOps?", "Quais informações ainda estão faltando?", "O que mudou desde a última reunião?"];
const playbooks = [
  { key: "FinOps", product: "IBM Cloudability + Turbonomic", question: "Como custos são alocados por produto e quem aprova otimizações?", workshop: "FinOps Discovery Workshop" },
  { key: "Trusted Data", product: "watsonx.data + IBM Guardium", question: "Quais fontes são críticas e onde existem dados sensíveis?", workshop: "Trusted Data Workshop" },
  { key: "AI Governance", product: "watsonx.governance + watsonx.ai", question: "Como modelos, riscos e evidências são aprovados?", workshop: "AI Governance Workshop" },
  { key: "Hybrid Cloud", product: "Red Hat OpenShift + Terraform", question: "Quais workloads exigem portabilidade e consistência?", workshop: "Hybrid Cloud Architecture Review" },
  { key: "Automation", product: "watsonx Orchestrate + IBM Concert", question: "Quais tarefas e decisões se repetem toda semana?", workshop: "Automation Discovery Workshop" },
  { key: "App Modernization", product: "OpenShift + Instana", question: "Quais aplicações seguram o roadmap de negócio?", workshop: "Modernization Assessment" },
];
const statusLabel: Record<string, string> = { proposal: "Proposta", accepted: "Aceita", in_progress: "Em andamento", completed: "Concluída", discarded: "Descartada", snoozed: "Adiada", draft: "Rascunho", validating: "Em validação", qualified: "Qualificada" };
const statusTone = (status: string) => status === "qualified" || status === "completed" ? "green" : status === "discarded" ? "gray" : status === "in_progress" ? "cyan" : status === "accepted" ? "blue" : status === "snoozed" ? "warm-gray" : "purple";
const formatDate = (value?: string | null) => value ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value)) : "Sem prazo";
const pageLoadedAt = Date.now();

export default function Home({ mode = "demo", userName = "Visitante" }: { mode?: "demo" | "private"; userName?: string }) {
  const privateMode = mode === "private";
  const [active, setActive] = useState<(typeof nav)[number]["id"]>("home");
  const [accountMode, setAccountMode] = useState<(typeof accountModes)[number]["id"]>("overview");
  const [data, setData] = useState<ApiData>(emptyData);
  const [selectedId, setSelectedId] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [notice, setNotice] = useState("");
  const [briefing, setBriefing] = useState<Briefing | null>(null);
  const [briefMeta, setBriefMeta] = useState<{ provider: string; model?: string | null; cached: boolean } | null>(null);
  const [aiStatus, setAIStatus] = useState<AIStatus | null>(null);
  const [copilot, setCopilot] = useState(false);
  const [copilotMode, setCopilotMode] = useState<"ask" | "prepare" | "next">("ask");
  const [question, setQuestion] = useState("");
  const [chatResult, setChatResult] = useState<ChatResult | null>(null);
  const [preparation, setPreparation] = useState<Record<string, unknown> | null>(null);
  const [commandOpen, setCommandOpen] = useState(false);
  const [commandQuery, setCommandQuery] = useState("");
  const [modal, setModal] = useState<"new-account" | "information" | "stakeholder" | "action" | "research" | null>(null);
  const [editingStakeholder, setEditingStakeholder] = useState<Stakeholder | null>(null);
  const [editingAction, setEditingAction] = useState<Action | null>(null);
  const [informationDraft, setInformationDraft] = useState<Record<string, unknown> | null>(null);
  const [informationPreview, setInformationPreview] = useState<Record<string, unknown> | null>(null);
  const [radarFilter, setRadarFilter] = useState<"all" | Priority>("all");

  const endpoint = `/api/accounts?scope=${mode}`;
  const load = useCallback(async () => {
    const response = await fetch(endpoint, { cache: "no-store" });
    if (response.ok) {
      const payload = await response.json() as ApiData;
      setData({ ...emptyData, ...payload });
      setSelectedId((current) => current && payload.discoveries.some((item) => item.id === current) ? current : payload.discoveries[0]?.id || "");
    }
    setLoading(false);
  }, [endpoint]);
  useEffect(() => {
    const timer = window.setTimeout(() => void load(), 0);
    return () => window.clearTimeout(timer);
  }, [load]);
  useEffect(() => {
    if (!privateMode) return;
    void fetch("/api/briefing", { cache: "no-store" }).then(async (response) => response.ok ? response.json() as Promise<BriefingResponse> : null).then((payload) => { if (payload?.briefing) { setBriefing(payload.briefing); setBriefMeta({ provider: payload.provider || "fallback", model: payload.model, cached: Boolean(payload.cached) }); } });
    void fetch("/api/ai/status", { cache: "no-store" }).then(async (response) => response.ok ? response.json() as Promise<AIStatus> : null).then((payload) => payload && setAIStatus(payload));
  }, [privateMode]);
  useEffect(() => {
    const handler = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen((current) => !current); }
      if (event.key === "Escape") { setCommandOpen(false); setModal(null); }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, []);

  const selected = data.discoveries.find((item) => item.id === selectedId) || data.discoveries[0];
  const accountEvents = data.accountEvents.filter((item) => item.discoveryId === selected?.id);
  const memory = data.memories.find((item) => item.discoveryId === selected?.id);
  const actions = data.actions.filter((item) => item.discoveryId === selected?.id).filter((item) => item.status !== "discarded");
  const hypotheses = data.hypotheses.filter((item) => item.discoveryId === selected?.id);
  const stakeholders = data.stakeholders.filter((item) => item.discoveryId === selected?.id);
  const meetings = data.meetings.filter((item) => item.discoveryId === selected?.id);
  const plan = data.plans.find((item) => item.discoveryId === selected?.id);
  const documents = data.documents.filter((item) => item.discoveryId === selected?.id);
  const relationships = data.relationships.filter((item) => item.discoveryId === selected?.id);
  const graphLayouts = data.graphLayouts.filter((item) => item.discoveryId === selected?.id);
  const signals = data.externalSignals.filter((item) => item.discoveryId === selected?.id);
  const portfolioActions = [...data.actions].filter((item) => !["completed", "discarded", "snoozed"].includes(item.status)).sort((a, b) => b.priorityScore - a.priorityScore);
  const filteredAccounts = radarFilter === "all" ? data.discoveries : data.discoveries.filter((item) => item.priority === radarFilter);
  const sponsor = stakeholders.find((person) => person.source === "manual" && person.influence === "Alta" && person.stance === "Aliado") || stakeholders.find((person) => person.source === "manual" && /chief|diretor|vp/i.test(person.role));

  const notify = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(""), 4200); };
  const post = async (body: Record<string, unknown>) => fetch("/api/accounts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...body, scope: mode }) });
  const mutate = async (body: Record<string, unknown>, success: string) => {
    if (!privateMode) { window.location.assign("/signin-with-chatgpt?return_to=%2Fworkspace"); return null; }
    setSaving(true);
    const response = await post(body);
    const payload = await response.json() as Record<string, unknown>;
    if (response.ok) { await load(); notify(success); } else notify(String(payload.error || "Não foi possível concluir a ação."));
    setSaving(false);
    return response.ok ? payload : null;
  };
  const openAccount = useCallback((accountId: string, nextMode: typeof accountMode = "overview") => { setSelectedId(accountId); setActive("accounts"); setAccountMode(nextMode); window.scrollTo({ top: 0, behavior: "smooth" }); }, []);
  const ask = async (event?: FormEvent) => {
    event?.preventDefault();
    if (!selected || !question.trim()) return;
    if (!privateMode) { setChatResult({ answer: "A demonstração não consome IA. Entre no workspace para conversar com a memória de uma conta real.", citations: [], confidence: 100, aiStatus: "demo", suggestedActions: [] }); return; }
    setSaving(true);
    const response = await post({ action: "ask", id: selected.id, question });
    const payload = await response.json() as ChatResult & { error?: string };
    if (response.ok) setChatResult(payload); else notify(payload.error || "Não foi possível responder.");
    setSaving(false);
  };
  const prepareConversation = async () => {
    if (!selected || !privateMode) return;
    setSaving(true);
    const response = await post({ action: "prepare_conversation", id: selected.id, focus: question || actions[0]?.conversation.theme || "próxima conversa" });
    const payload = await response.json() as { preparation?: Record<string, unknown>; provider?: string; model?: string | null; citations?: Evidence[]; error?: string };
    if (response.ok) setPreparation({ ...(payload.preparation || {}), provider: payload.provider, model: payload.model, citations: payload.citations }); else notify(payload.error || "Não foi possível preparar a conversa.");
    setSaving(false);
  };
  const actionStatus = async (action: Action, status: string, extras: Record<string, unknown> = {}) => { await mutate({ action: "action_status", id: action.discoveryId, actionId: action.id, status, ...extras }, "Decisão registrada; a fila usará esse feedback na ordenação."); };

  const hierarchyRelationships: GraphRelationship[] = relationships.length ? relationships.map((item) => ({ id: item.id, source: item.sourceStakeholderId, target: item.targetStakeholderId, type: item.relationType as GraphRelationship["type"], label: item.label, confirmed: item.status === "confirmed", evidence: item.evidence.map((source, index) => ({ id: `${item.id}-${index}`, title: source.title, excerpt: source.excerpt, sourceType: source.sourceType, updatedAt: source.occurredAt })) })) : stakeholders.filter((person) => person.reportsToId).map((person) => ({ id: `local-${person.id}`, source: person.id, target: person.reportsToId!, type: "reporta_para", confirmed: true }));
  const savedPositions = graphLayouts.reduce<Partial<Record<RelationshipGraphMode, Record<string, GraphPosition>>>>((result, layout) => { result[layout.mode] = Object.fromEntries(layout.nodes.map((node) => [node.id, { x: node.x, y: node.y }])); return result; }, {});

  const commands = useMemo(() => {
    const base = [
      { label: "Ir para Início", hint: "Navegação", run: () => setActive("home") },
      { label: "Abrir Radar da carteira", hint: "Navegação", run: () => setActive("radar") },
      { label: "Adicionar informação", hint: "Ação", run: () => selected && setModal("information") },
      { label: "Adicionar stakeholder", hint: "Ação", run: () => { setEditingStakeholder(null); setModal("stakeholder"); } },
      { label: "Preparar próxima conversa", hint: "Copiloto", run: () => { setCopilot(true); setCopilotMode("prepare"); } },
      { label: "Perguntar sobre a conta", hint: "Copiloto", run: () => { setCopilot(true); setCopilotMode("ask"); } },
    ];
    return [...base, ...data.discoveries.map((account) => ({ label: account.customerName, hint: "Conta", run: () => openAccount(account.id) }))].filter((item) => item.label.toLowerCase().includes(commandQuery.toLowerCase()));
  }, [commandQuery, data.discoveries, selected, openAccount]);

  if (loading) return <main className="v5-loading"><div><Watson size={32} /></div><SkeletonText heading width="14rem" /><SkeletonText paragraph lineCount={3} width="22rem" /></main>;

  return <div className={`v5-shell ${copilot ? "has-copilot" : ""}`}>
    <Theme theme="g100"><Header aria-label="watson Account Intelligence" className="v5-header"><SkipToContent /><HeaderMenuButton aria-label="Menu" isActive={mobileNav} onClick={() => setMobileNav(!mobileNav)} renderMenuIcon={<Menu />} renderCloseIcon={<Close />} /><HeaderName prefix="watson" href="#" onClick={(event) => { event.preventDefault(); setActive("home"); }}>Account Intelligence</HeaderName><div className="v5-header-state"><i /> Proativo · antes do CRM</div><button className="v5-command-trigger" onClick={() => setCommandOpen(true)}><Search size={16} /><span>Buscar ou executar</span><kbd>⌘ K</kbd></button><HeaderGlobalBar><HeaderGlobalAction aria-label="Abrir copiloto" onClick={() => setCopilot(!copilot)}><Chat /></HeaderGlobalAction><HeaderGlobalAction aria-label={userName}><UserAvatar /></HeaderGlobalAction></HeaderGlobalBar></Header>
      <SideNav aria-label="Navegação principal" expanded={mobileNav} isPersistent={false} isFixedNav onOverlayClick={() => setMobileNav(false)} className="v5-sidenav"><SideNavItems><p className="v5-nav-label">Workspace</p>{nav.map((item) => <SideNavLink key={item.id} href="#" renderIcon={item.icon} isActive={active === item.id} onClick={(event) => { event.preventDefault(); setActive(item.id); setMobileNav(false); }}>{item.label}</SideNavLink>)}</SideNavItems><div className="v5-side-foot"><strong>V5 · Proactive copilot</strong><span><i className={aiStatus?.provider === "google-gemini" ? "gemini" : aiStatus?.provider === "ibm-watsonx" ? "watsonx" : "fallback"} />{aiStatus?.provider === "google-gemini" ? "Gemini experimental" : aiStatus?.provider === "ibm-watsonx" ? "watsonx ativo" : "Fallback operacional"}</span><small>{privateMode ? "Workspace privado" : "Demonstração pública"}</small></div></SideNav>
    </Theme>

    <main className="v5-main" id="main-content">
      {notice && <div className="v5-toast" role="status">{notice}</div>}
      <div className="v5-topbar"><div><span>{privateMode ? `Olá, ${userName.split(" ")[0]}` : "Demonstração pública"}</span><strong>{active === "home" ? "Seu briefing operacional" : nav.find((item) => item.id === active)?.label}</strong></div><div>{selected && active !== "home" && <label className="v5-account-switch"><span>Conta ativa</span><select value={selected.id} onChange={(event) => openAccount(event.target.value, accountMode)}>{data.discoveries.map((account) => <option key={account.id} value={account.id}>{account.customerName}</option>)}</select></label>}<Button kind="secondary" renderIcon={Add} onClick={() => privateMode ? selected ? setModal("information") : setModal("new-account") : window.location.assign("/signin-with-chatgpt?return_to=%2Fworkspace")}>Adicionar informação</Button></div></div>

      {active === "home" && <HomeView data={data} briefing={briefing} briefMeta={briefMeta} privateMode={privateMode} actions={portfolioActions} onOpen={openAccount} onDecision={actionStatus} onRefresh={async () => { if (!privateMode) return; setSaving(true); const response = await fetch("/api/briefing", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ force: true }) }); const payload = await response.json() as BriefingResponse; if (response.ok && payload.briefing) { setBriefing(payload.briefing); setBriefMeta({ provider: payload.provider || "fallback", model: payload.model, cached: false }); notify("Briefing recalculado."); } setSaving(false); }} saving={saving} />}

      {active === "accounts" && selected && <section className="v5-page"><header className="v5-account-hero"><div><span>{selected.industry} · {selected.companySize}</span><h1>{selected.customerName}</h1><p>{memory?.executiveSummary || selected.challengeSummary}</p><div className="v5-hero-tags"><Tag type={selected.dataClassification === "confidential" ? "red" : "cyan"}>{selected.dataClassification === "confidential" ? "Confidencial · Gemini bloqueado" : "Ambiente de teste"}</Tag><Tag type="gray">{memory?.aiStatus || "fallback"}</Tag><Tag type={selected.priority === "Alta" ? "red" : selected.priority === "Média" ? "purple" : "green"}>{selected.priority} prioridade</Tag></div></div><div className="v5-maturity"><strong>{selected.progress}%</strong><span>Maturidade pré-CRM</span><ProgressBar label="Maturidade" hideLabel value={selected.progress} /></div></header><nav className="v5-account-tabs" aria-label="Modos do workspace da conta">{accountModes.map((item) => <button key={item.id} className={accountMode === item.id ? "active" : ""} onClick={() => setAccountMode(item.id)}>{item.label}</button>)}</nav>
        {accountMode === "overview" && <AccountOverview account={selected} memory={memory} actions={actions} hypotheses={hypotheses} stakeholders={stakeholders} events={accountEvents} privateMode={privateMode} onMode={setAccountMode} onDecision={actionStatus} onEditAction={(action) => { setEditingAction(action); setModal("action"); }} />}
        {accountMode === "activity" && <AccountActivity account={selected} memory={memory} events={accountEvents} meetings={meetings} documents={documents} privateMode={privateMode} saving={saving} onMeeting={(payload) => mutate({ action: "meeting", id: selected.id, ...payload }, "Reunião analisada; memória e ações foram atualizadas.")} onUpload={(file) => uploadDocument(file, selected.id, mode, notify, load, setSaving)} />}
        {accountMode === "relationships" && <div className="v5-relationship-layout"><section className="v5-section-head"><div><span>Inteligência de relacionamento</span><h2>Organograma e rede de influência</h2><p>Explore pessoas, arraste posições e conecte relações políticas ou hierárquicas. Cada mudança permanece salva nesta conta.</p></div><Button size="sm" renderIcon={Add} disabled={!privateMode} onClick={() => { setEditingStakeholder(null); setModal("stakeholder"); }}>Adicionar pessoa</Button></section><RelationshipGraph stakeholders={stakeholders.map((person) => ({ ...person, isSponsor: person.id === sponsor?.id, evidence: accountEvents.filter((event) => event.sourceId === person.id).map((event) => ({ id: event.id, title: event.title, excerpt: event.content, sourceType: event.sourceType, confidence: event.confidence, updatedAt: event.occurredAt })), recommendedApproach: `Conecte ${person.priorities[0] || person.area} à hipótese líder e valide o próximo passo com evidência.` }))} relationships={hierarchyRelationships} savedPositions={savedPositions} sponsorId={sponsor?.id} readOnly={!privateMode} missingRelationshipNodeIds={stakeholders.filter((person) => !hierarchyRelationships.some((relation) => relation.source === person.id || relation.target === person.id)).map((person) => person.id)} onLayoutChange={(graphMode, positions) => { if (!privateMode) return; const nodes = Object.entries(positions).map(([nodeId, position]) => ({ id: nodeId, ...position })); void fetch(`/api/accounts/${selected.id}/graph-layout`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ mode: graphMode, nodes }) }); }} onCreateRelationship={async (relationship) => { await mutate({ action: "relationship", id: selected.id, source: relationship.source, target: relationship.target, type: relationship.type, label: relationship.label }, "Relação salva no mapa da conta."); }} onRequestEdit={(person) => { setEditingStakeholder(stakeholders.find((item) => item.id === person.id) || null); setModal("stakeholder"); }} onRequestAddStakeholder={() => { setEditingStakeholder(null); setModal("stakeholder"); }} /></div>}
        {accountMode === "strategy" && <AccountStrategy key={selected.id} account={selected} hypotheses={hypotheses} actions={actions} plan={plan} signals={signals} privateMode={privateMode} saving={saving} onDecision={actionStatus} onSavePlan={(payload) => mutate({ action: "plan_save", id: selected.id, ...payload }, "Account Plan salvo.")} onSuggest={() => mutate({ action: "plan_suggest", id: selected.id }, "Sugestão criada para comparação.")} onApply={() => mutate({ action: "plan_apply", id: selected.id }, "Sugestão aprovada e aplicada.")} onResearch={() => setModal("research")} />}
      </section>}

      {active === "radar" && <section className="v5-page"><PageHeading eyebrow="Radar da carteira" title="Decida onde investir tempo e relacionamento" description="Combine potencial, maturidade, risco, cobertura política e evolução das hipóteses — com drill-down direto para a conta." /><div className="v5-filterbar"><span>Filtrar risco</span>{(["all", "Alta", "Média", "Baixa"] as const).map((filter) => <button key={filter} className={radarFilter === filter ? "active" : ""} onClick={() => setRadarFilter(filter)}>{filter === "all" ? "Todas" : filter}</button>)}</div><div className="v5-chart-grid"><section className="v5-card v5-span-2"><PortfolioBubbleChart accounts={filteredAccounts} /></section><section className="v5-card"><CardHeader eyebrow="Prioridade" title="Contas para explorar" /><div className="v5-account-rank">{[...filteredAccounts].sort((a, b) => (b.scores[0]?.alignment || 0) - (a.scores[0]?.alignment || 0)).map((account) => <button key={account.id} onClick={() => openAccount(account.id)}><span><strong>{account.customerName}</strong><small>{account.scores[0]?.short || "Sem tema líder"}</small></span><em>{account.scores[0]?.alignment || 0}%</em><ArrowRight /></button>)}</div></section><section className="v5-card"><StakeholderCoverageChart accounts={filteredAccounts} stakeholders={data.stakeholders} /></section><section className="v5-card v5-span-2"><HypothesisConfidenceChart accounts={filteredAccounts} snapshots={data.snapshots} /></section></div><section className="v5-card v5-heatmap-card"><CardHeader eyebrow="Heatmap" title="Aderência IBM por conta" side={<Tag type="cyan">Carbon pattern</Tag>} /><div className="v5-heatmap"><div className="head"><strong>Conta</strong>{playbooks.map((book) => <span key={book.key}>{book.key}</span>)}</div>{filteredAccounts.map((account) => <button key={account.id} onClick={() => openAccount(account.id, "strategy")}><strong>{account.customerName}<small>{account.progress}% madura</small></strong>{playbooks.map((book) => { const score = account.scores.find((item) => item.short === book.key)?.alignment || 0; return <i key={book.key} data-level={score >= 75 ? "high" : score >= 50 ? "medium" : "low"} style={{ opacity: Math.max(.28, score / 100) }}><em>{score}</em></i>; })}</button>)}</div></section></section>}

      {active === "settings" && <SettingsView key={selected?.id || "none"} data={data} selected={selected} aiStatus={aiStatus} privateMode={privateMode} onSettings={(payload) => selected && mutate({ action: "account_settings", id: selected.id, ...payload }, "Política da conta atualizada.")} />}
    </main>

    <CopilotPanel open={copilot} mode={copilotMode} setMode={setCopilotMode} selected={selected} action={actions[0]} question={question} setQuestion={setQuestion} result={chatResult} preparation={preparation} saving={saving} onClose={() => setCopilot(false)} onAsk={ask} onPrepare={prepareConversation} onNavigate={(sourceId) => { setCopilot(false); setActive("accounts"); setAccountMode("activity"); window.setTimeout(() => document.getElementById(`source-${sourceId}`)?.scrollIntoView({ behavior: "smooth" }), 80); }} onDecision={actionStatus} />

    {commandOpen && <div className="v5-command-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setCommandOpen(false)}><div className="v5-command" role="dialog" aria-modal="true" aria-label="Paleta de comandos"><header><Search /><input autoFocus value={commandQuery} onChange={(event) => setCommandQuery(event.target.value)} placeholder="Conta, tela ou ação…" onKeyDown={(event) => { if (event.key === "Enter" && commands[0]) { commands[0].run(); setCommandOpen(false); setCommandQuery(""); } }} /><kbd>esc</kbd></header><div>{commands.slice(0, 9).map((command) => <button key={`${command.hint}-${command.label}`} onClick={() => { command.run(); setCommandOpen(false); setCommandQuery(""); }}><span>{command.label}</span><small>{command.hint}</small></button>)}</div><footer>Use ⌘/Ctrl + K em qualquer tela</footer></div></div>}

    <NewAccountModal open={modal === "new-account"} saving={saving} onClose={() => setModal(null)} onSave={async (payload) => { const result = await mutate({ action: "create", ...payload }, "Conta criada."); if (result) setModal(null); }} />
    <InformationModal open={modal === "information"} saving={saving} account={selected} preview={informationPreview} onClose={() => { setModal(null); setInformationDraft(null); setInformationPreview(null); }} onBack={() => setInformationPreview(null)} onPreview={async (payload) => { if (!selected) return; setSaving(true); const response = await fetch(`/api/accounts/${selected.id}/information/preview`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const result = await response.json() as { preview?: Record<string, unknown>; error?: string }; if (response.ok && result.preview) { setInformationDraft(payload); setInformationPreview(result.preview); } else notify(result.error || "Não foi possível gerar a prévia."); setSaving(false); }} onConfirm={async () => { if (!selected || !informationDraft) return; const result = await mutate({ action: "information", id: selected.id, ...informationDraft, confirmed: true }, "Informação aprovada; memória e ações recalculadas."); if (result) { setModal(null); setInformationDraft(null); setInformationPreview(null); } }} />
    <StakeholderModal open={modal === "stakeholder"} account={selected} stakeholder={editingStakeholder} people={stakeholders} saving={saving} onClose={() => setModal(null)} onSave={async (payload) => { if (!selected) return; const result = await mutate({ action: "stakeholder_upsert", id: selected.id, stakeholderId: editingStakeholder?.id, ...payload }, "Stakeholder salvo e inteligência de relacionamento atualizada."); if (result) setModal(null); }} />
    <ActionModal open={modal === "action"} action={editingAction} saving={saving} onClose={() => setModal(null)} onSave={async (payload) => { if (!editingAction) return; await actionStatus(editingAction, String(payload.status), payload); setModal(null); }} />
    <ResearchModal open={modal === "research"} account={selected} saving={saving} onClose={() => setModal(null)} onResearch={async (payload) => { if (!selected) return; setSaving(true); const response = await fetch(`/api/accounts/${selected.id}/research`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const result = await response.json() as { error?: string }; if (response.ok) { await load(); notify("Pesquisa concluída; os sinais aguardam sua aprovação."); setModal(null); } else notify(result.error || "Pesquisa indisponível."); setSaving(false); }} />
  </div>;
}

function HomeView({ data, briefing, briefMeta, privateMode, actions, onOpen, onDecision, onRefresh, saving }: { data: ApiData; briefing: Briefing | null; briefMeta: { provider: string; model?: string | null; cached: boolean } | null; privateMode: boolean; actions: Action[]; onOpen: (id: string, mode?: "overview" | "activity" | "relationships" | "strategy") => void; onDecision: (action: Action, status: string, extras?: Record<string, unknown>) => void; onRefresh: () => void; saving: boolean }) {
  const changes = briefing?.changes || data.accountEvents.slice(0, 6).map((event) => `${data.discoveries.find((account) => account.id === event.discoveryId)?.customerName}: ${event.title}`);
  const meetings = data.meetings.filter((meeting) => meeting.meetingStatus === "scheduled");
  const stale = data.accountEvents.filter((event) => event.evidenceStatus === "stale" || pageLoadedAt - new Date(event.occurredAt).getTime() > 90 * 86400000);
  return <section className="v5-page"><PageHeading eyebrow="Briefing diário" title={briefing?.headline || "O que merece sua atenção hoje"} description={briefing?.summary || "A plataforma cruza memória, relações e maturidade para priorizar as próximas decisões — sempre com aprovação humana."} action={<div className="v5-heading-actions"><Tag type={briefMeta?.provider === "google-gemini" ? "purple" : briefMeta?.provider === "ibm-watsonx" ? "blue" : "gray"}>{briefMeta?.provider || "fallback determinístico"}{briefMeta?.cached ? " · cache" : ""}</Tag>{privateMode && <Button kind="ghost" size="sm" renderIcon={Renew} disabled={saving} onClick={onRefresh}>Atualizar</Button>}</div>} />
    <div className="v5-attention-grid">{actions.slice(0, 3).map((action, index) => <article key={action.id} className={`v5-attention-card rank-${index + 1}`}><header><span>0{index + 1}</span><Tag type={statusTone(action.status)}>{action.priorityScore} prioridade</Tag></header><small>{data.discoveries.find((account) => account.id === action.discoveryId)?.customerName} · Next Best Action</small><h2>{action.title}</h2><p>{action.whyNow || action.rationale}</p><dl><div><dt>Impacto</dt><dd>{action.impact}</dd></div><div><dt>Confiança</dt><dd>{action.confidence}%</dd></div><div><dt>Esforço</dt><dd>{action.effort}/100</dd></div></dl><footer><button onClick={() => onOpen(action.discoveryId)}>Ver evidências <ArrowRight /></button>{privateMode && action.status === "proposal" && <Button size="sm" onClick={() => onDecision(action, "accepted")}>Aceitar</Button>}</footer></article>)}{!actions.length && <article className="v5-attention-card empty"><Checkmark size={32} /><h2>Nenhuma ação crítica</h2><p>Adicione uma interação para atualizar a leitura da carteira.</p></article>}</div>
    <div className="v5-home-grid"><section className="v5-card v5-span-2"><CardHeader eyebrow="Mudanças desde o último acesso" title="Memória viva da carteira" side={<span className="v5-live"><i /> análise progressiva</span>} /><div className="v5-change-feed">{changes.slice(0, 8).map((change, index) => <article key={`${change}-${index}`}><i /><span><strong>{change}</strong><small>{index < 3 ? "Nova evidência ou atualização recente" : "Incluído no briefing"}</small></span></article>)}</div></section><section className="v5-card"><CardHeader eyebrow="Próxima melhor conversa" title={actions[0]?.conversation.stakeholder || "Mapeie um sponsor"} /><div className="v5-conversation-card"><span>{actions[0]?.conversation.theme || "Cobertura executiva"}</span><p>{actions[0]?.conversation.opener || "Confirme quem decide, influencia e patrocina a principal iniciativa da conta."}</p>{actions[0]?.conversation.questions?.slice(0, 3).map((item) => <button key={item}>{item}</button>)}</div></section><section className="v5-card"><CardHeader eyebrow="Reuniões" title="Precisam de preparação" /><div className="v5-mini-list">{meetings.slice(0, 5).map((meeting) => <button key={meeting.id} onClick={() => onOpen(meeting.discoveryId, "activity")}><Calendar /><span><strong>{meeting.title}</strong><small>{data.discoveries.find((account) => account.id === meeting.discoveryId)?.customerName} · {formatDate(meeting.scheduledAt)}</small></span></button>)}{!meetings.length && <Empty text="Nenhuma reunião futura registrada." />}</div></section><section className="v5-card"><CardHeader eyebrow="Qualidade da memória" title="Evidências desatualizadas" /><div className="v5-mini-list">{stale.slice(0, 5).map((event) => <button key={event.id} onClick={() => onOpen(event.discoveryId, "activity")}><Asleep /><span><strong>{event.title}</strong><small>{data.discoveries.find((account) => account.id === event.discoveryId)?.customerName} · {formatDate(event.occurredAt)}</small></span></button>)}{!stale.length && <Empty text="Nenhuma evidência crítica desatualizada." />}</div></section><section className="v5-card v5-span-2"><CardHeader eyebrow="Carteira" title="Maturidade e próxima decisão" /><div className="v5-portfolio-table">{data.discoveries.map((account) => <button key={account.id} onClick={() => onOpen(account.id)}><span><strong>{account.customerName}</strong><small>{account.stage}</small></span><i><b style={{ width: `${account.progress}%` }} /></i><em>{account.progress}%</em><Tag type={account.priority === "Alta" ? "red" : account.priority === "Média" ? "purple" : "green"}>{account.priority}</Tag><ArrowRight /></button>)}</div></section></div>
  </section>;
}

function AccountOverview({ account, memory, actions, hypotheses, stakeholders, events, privateMode, onMode, onDecision, onEditAction }: { account: Discovery; memory?: Memory; actions: Action[]; hypotheses: Hypothesis[]; stakeholders: Stakeholder[]; events: AccountEvent[]; privateMode: boolean; onMode: (mode: "overview" | "activity" | "relationships" | "strategy") => void; onDecision: (action: Action, status: string, extras?: Record<string, unknown>) => void; onEditAction: (action: Action) => void }) {
  const action = actions[0]; const conversation = action?.conversation;
  return <div className="v5-account-grid"><section className="v5-card v5-span-2"><CardHeader eyebrow="Memória executiva" title="O que importa agora" side={<Tag type="gray">versão {memory?.version || 1}</Tag>} /><h2 className="v5-executive-summary">{memory?.executiveSummary || account.challengeSummary}</h2><div className="v5-change-chips">{memory?.changes.slice(0, 4).map((item) => <span key={item}>{item}</span>)}</div></section><section className="v5-card v5-nba"><CardHeader eyebrow="Next Best Action" title={action?.title || account.nextEngagement} side={action && <strong>{action.priorityScore}</strong>} /><p>{action?.rationale || "Aprofunde o contexto da conta."}</p>{action && <><dl><div><dt>Por que agora</dt><dd>{action.whyNow}</dd></div><div><dt>Resultado esperado</dt><dd>{action.expectedOutcome}</dd></div><div><dt>Stakeholder</dt><dd>{conversation?.stakeholder || "A identificar"}</dd></div></dl><div className="v5-action-buttons">{privateMode && <><Button size="sm" onClick={() => onDecision(action, "accepted")}>Aceitar</Button><Button size="sm" kind="tertiary" onClick={() => onEditAction(action)}>Editar / adiar</Button></>}<button onClick={() => onMode("strategy")}>Ver estratégia <ArrowRight /></button></div></>}</section><section className="v5-card"><CardHeader eyebrow="Memória confiável" title="Sabemos, supomos e falta descobrir" /><div className="v5-memory-summary"><MemoryMini title="Sabemos" count={memory?.known.length || 0} tone="known" items={memory?.known || []} /><MemoryMini title="Supomos" count={memory?.assumptions.length || 0} tone="assumption" items={memory?.assumptions || []} /><MemoryMini title="Falta descobrir" count={memory?.gaps.length || 0} tone="gap" items={memory?.gaps || []} /><MemoryMini title="Desatualizado" count={events.filter((item) => item.evidenceStatus === "stale").length} tone="stale" items={events.filter((item) => item.evidenceStatus === "stale").map((item) => item.title)} /></div><button className="v5-text-action" onClick={() => onMode("activity")}>Explorar memória e fontes <ArrowRight /></button></section><section className="v5-card"><CardHeader eyebrow="Próxima melhor conversa" title={conversation?.stakeholder || "Stakeholder a identificar"} /><div className="v5-conversation-detail"><Tag type="cyan">{conversation?.theme || hypotheses[0]?.capabilityKey || "Descoberta"}</Tag><p>{conversation?.opener || "Valide o problema, quem decide e o que define sucesso."}</p><ol>{conversation?.questions?.map((item) => <li key={item}>{item}</li>)}</ol><div><strong>Possível objeção</strong><span>{conversation?.objection || "Prioridade ou urgência ainda não confirmada."}</span></div><div><strong>Critério de sucesso</strong><span>{conversation?.successCriterion || "Próximo passo acordado com responsável e prazo."}</span></div></div></section><section className="v5-card v5-span-2"><CardHeader eyebrow="Hipóteses de oportunidade" title="O que pode ganhar força" side={<button className="v5-text-action" onClick={() => onMode("strategy")}>Abrir estratégia</button>} /><div className="v5-hypothesis-grid">{hypotheses.slice(0, 3).map((hypothesis) => <article key={hypothesis.id}><header><Tag type={statusTone(hypothesis.stage)}>{statusLabel[hypothesis.stage] || hypothesis.stage}</Tag><strong>{hypothesis.confidence}%</strong></header><h3>{hypothesis.title}</h3><p>{hypothesis.problem}</p><small>{hypothesis.gaps[0] || hypothesis.nextStep}</small></article>)}{!hypotheses.length && <Empty text="Nenhuma hipótese atingiu evidência mínima." />}</div></section><section className="v5-card"><CardHeader eyebrow="Mapa político" title="Stakeholders-chave" side={<button className="v5-text-action" onClick={() => onMode("relationships")}>Explorar</button>} /><div className="v5-people-list">{stakeholders.slice(0, 5).map((person) => <button key={person.id} onClick={() => onMode("relationships")}><span>{person.name.split(" ").map((part) => part[0]).slice(0, 2)}</span><div><strong>{person.name}</strong><small>{person.role} · {person.influence}</small></div><Tag type={person.stance === "Aliado" ? "green" : person.stance === "Resistente" ? "red" : "gray"}>{person.stance}</Tag></button>)}</div></section></div>;
}

function AccountActivity({ account, memory, events, meetings, documents, privateMode, saving, onMeeting, onUpload }: { account: Discovery; memory?: Memory; events: AccountEvent[]; meetings: Meeting[]; documents: AccountDocument[]; privateMode: boolean; saving: boolean; onMeeting: (payload: Record<string, unknown>) => void; onUpload: (file: File) => void }) {
  return <div className="v5-activity-grid"><section className="v5-card v5-span-2"><CardHeader eyebrow="Memória da conta" title="Sabemos, supomos, falta descobrir e desatualizado" side={<Tag type="gray">{memory?.aiStatus || "fallback"}</Tag>} /><div className="v5-memory-board"><MemoryColumn title="Sabemos" tone="known" items={memory?.known || []} /><MemoryColumn title="Supomos" tone="assumption" items={memory?.assumptions || []} /><MemoryColumn title="Falta descobrir" tone="gap" items={memory?.gaps || []} /><MemoryColumn title="Desatualizado" tone="stale" items={events.filter((item) => item.evidenceStatus === "stale").map((item) => item.title)} /></div></section><section className="v5-card"><CardHeader eyebrow="Reuniões" title={`Registrar em ${account.customerName}`} /><div className="v5-meeting-list">{meetings.slice(0, 3).map((meeting) => <article key={meeting.id}><Calendar /><span><strong>{meeting.title}</strong><small>{meeting.meetingStatus || "concluída"} · {formatDate(meeting.scheduledAt || meeting.createdAt)}</small></span></article>)}</div><MeetingForm onSave={onMeeting} saving={saving} readonly={!privateMode} /></section><section className="v5-card"><CardHeader eyebrow="Documentos" title="Fontes recuperáveis" side={privateMode ? <label className="v5-upload">Adicionar<input type="file" accept=".pdf,.docx,.txt,.md" onChange={(event) => event.target.files?.[0] && onUpload(event.target.files[0])} /></label> : undefined} /><div className="v5-document-list">{documents.map((document) => <article key={document.id}><Document /><span><strong>{document.name}</strong><small>{document.status} · {(document.sizeBytes / 1024).toFixed(0)} KB</small><p>{document.summary}</p></span></article>)}{!documents.length && <Empty text={privateMode ? "PDF, DOCX, TXT ou Markdown, até 15 MB." : "Documentos reais ficam no workspace privado."} />}</div></section><section className="v5-card v5-span-2"><CardHeader eyebrow="Timeline unificada" title="Tudo o que formou a memória" /><div className="v5-timeline">{events.map((event) => <article id={`source-${event.sourceId || event.id}`} key={event.id}><i className={event.evidenceStatus} /><div><span>{event.sourceType} · {event.confidence}% confiança</span><h3>{event.title}</h3><p>{event.content}</p><small>{formatDate(event.occurredAt)}</small></div><Tag type={event.evidenceStatus === "confirmed" ? "green" : event.evidenceStatus === "assumption" ? "purple" : event.evidenceStatus === "stale" ? "warm-gray" : "red"}>{event.evidenceStatus}</Tag></article>)}</div></section></div>;
}

function AccountStrategy({ account, hypotheses, actions, plan, signals, privateMode, saving, onDecision, onSavePlan, onSuggest, onApply, onResearch }: { account: Discovery; hypotheses: Hypothesis[]; actions: Action[]; plan?: Plan; signals: ExternalSignal[]; privateMode: boolean; saving: boolean; onDecision: (action: Action, status: string, extras?: Record<string, unknown>) => void; onSavePlan: (payload: Record<string, unknown>) => void; onSuggest: () => void; onApply: () => void; onResearch: () => void }) {
  const [draft, setDraft] = useState<Record<string, string>>(() => plan ? Object.fromEntries(["priorities", "initiatives", "objectives", "risks", "ecosystem", "relationship", "plan30", "plan60", "plan90"].map((key) => [key, ((plan as unknown as Record<string, string[]>)[key] || []).join("\n")])) : {});
  return <div className="v5-strategy-layout"><section className="v5-card v5-span-2"><CardHeader eyebrow="Temas IBM" title="Aderência, evidências e playbook contextual" side={<Tag type="cyan">Carbon Charts</Tag>} /><CarbonCapabilityChart scores={account.scores} /><div className="v5-playbooks">{account.scores.slice(0, 3).map((score) => { const book = playbooks.find((item) => item.key === score.short); return <article key={score.short}><header><Tag type={score.alignment >= 75 ? "red" : score.alignment >= 50 ? "purple" : "gray"}>{score.alignment}% alinhamento</Tag><strong>{score.short}</strong></header><p>{book?.product || score.name}</p><small>Pergunta recomendada</small><blockquote>{book?.question || score.action}</blockquote><footer>{book?.workshop || "Discovery workshop"}</footer></article>; })}</div></section><section className="v5-card"><CardHeader eyebrow="Hipóteses" title="Maturidade antes do CRM" /><div className="v5-hypothesis-stack">{hypotheses.map((hypothesis) => <article key={hypothesis.id}><header><Tag type={statusTone(hypothesis.stage)}>{statusLabel[hypothesis.stage] || hypothesis.stage}</Tag><strong>{hypothesis.confidence}%</strong></header><h3>{hypothesis.capabilityKey}</h3><p>{hypothesis.problem}</p><div><small>Critérios pendentes</small>{hypothesis.gaps.map((gap) => <span key={gap}>○ {gap}</span>)}</div><footer>{hypothesis.nextStep}</footer></article>)}</div></section><section className="v5-card"><CardHeader eyebrow="Pesquisa pública" title="Sinais externos propostos" side={privateMode && account.dataClassification === "test" ? <Button size="sm" kind="tertiary" renderIcon={Search} onClick={onResearch}>Pesquisar</Button> : undefined} />{account.dataClassification === "confidential" && <InlineNotification kind="warning" lowContrast title="Gemini bloqueado" subtitle="Conta confidencial usa watsonx ou fallback." hideCloseButton />}{signals.map((signal) => <article className="v5-signal" key={signal.id}><Tag type={signal.status === "approved" ? "green" : signal.status === "discarded" ? "gray" : "purple"}>{signal.status}</Tag><h3>{signal.title}</h3><p>{signal.summary}</p><a href={signal.sourceUrl} target="_blank" rel="noreferrer">{signal.publisher || "Abrir fonte"} <Launch /></a>{privateMode && signal.status === "proposed" && <div><button onClick={() => void fetch("/api/accounts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "external_signal_status", id: account.id, signalId: signal.id, status: "approved", scope: "private" }) }).then(() => window.location.reload())}>Aprovar</button><button onClick={() => void fetch("/api/accounts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "external_signal_status", id: account.id, signalId: signal.id, status: "discarded", scope: "private" }) }).then(() => window.location.reload())}>Descartar</button></div>}</article>)}{!signals.length && <Empty text="Pesquise sinais públicos sob demanda; nada entra na memória sem aprovação." />}</section><section className="v5-card v5-span-3"><CardHeader eyebrow="Account Plan" title="Plano humano enriquecido por IA" side={<div className="v5-inline-actions"><Button size="sm" kind="tertiary" disabled={!privateMode || saving} onClick={onSuggest}>Gerar sugestão</Button><Button size="sm" disabled={!privateMode || saving} onClick={() => onSavePlan(draft)}>Salvar plano</Button></div>} /><div className="v5-plan-grid">{[["priorities", "Prioridades estratégicas"], ["initiatives", "Iniciativas"], ["objectives", "Objetivos e métricas"], ["risks", "Riscos"], ["ecosystem", "Ecossistema"], ["relationship", "Plano de relacionamento"]].map(([key, label]) => <label key={key}><span>{label}</span><textarea value={draft[key] || ""} onChange={(event) => setDraft((current) => ({ ...current, [key]: event.target.value }))} rows={4} disabled={!privateMode} /></label>)}</div><div className="v5-horizons">{[["plan30", "30 dias"], ["plan60", "60 dias"], ["plan90", "90 dias"]].map(([key, label]) => <label key={key}><strong>{label}</strong><textarea value={draft[key] || ""} onChange={(event) => setDraft((current) => ({ ...current, [key]: event.target.value }))} rows={6} disabled={!privateMode} /></label>)}</div>{plan?.suggestion && Object.keys(plan.suggestion).length > 0 && <div className="v5-plan-suggestion"><header><span><WatsonHealthTextAnnotationToggle /> Proposta da IA</span><Tag type="purple">comparar antes de aplicar</Tag></header><div>{Object.entries(plan.suggestion).slice(0, 5).map(([key, items]) => <article key={key}><strong>{key}</strong>{items.map((item) => <p key={item}>+ {item}</p>)}</article>)}</div><Button size="sm" disabled={!privateMode} onClick={onApply}>Aprovar e aplicar</Button></div>}</section><section className="v5-card v5-span-3"><CardHeader eyebrow="Decisões" title="Ações e handoff humano" /><div className="v5-action-table">{actions.map((action) => <article key={action.id}><span><Tag type={statusTone(action.status)}>{statusLabel[action.status] || action.status}</Tag><strong>{action.title}</strong><small>{action.nextStep}</small></span><em>{action.priorityScore}</em>{privateMode && action.status === "proposal" && <Button size="sm" onClick={() => onDecision(action, "accepted")}>Aceitar</Button>}{action.type === "crm_handoff" && <Button size="sm" kind="tertiary" disabled={!hypotheses.some((hypothesis) => hypothesis.stage === "qualified")}>Copiar handoff CRM</Button>}</article>)}</div></section></div>;
}

function SettingsView({ data, selected, aiStatus, privateMode, onSettings }: { data: ApiData; selected?: Discovery; aiStatus: AIStatus | null; privateMode: boolean; onSettings: (payload: Record<string, unknown>) => void }) {
  const [classification, setClassification] = useState<Discovery["dataClassification"]>(selected?.dataClassification || "test"); const [domain, setDomain] = useState(selected?.companyDomain || "");
  return <section className="v5-page"><PageHeading eyebrow="Configurações" title="Governança, IA e integrações" description="Controles administrativos ficam aqui; fontes, confiança e status continuam visíveis no contexto de cada insight." /><InlineNotification kind="warning" lowContrast title="Ambiente experimental Gemini" subtitle="No tier gratuito, conteúdos enviados podem ser usados pelo Google para melhorar produtos. Use apenas contas de teste; contas confidenciais são bloqueadas automaticamente." hideCloseButton /><div className="v5-settings-grid"><section className="v5-card"><CardHeader eyebrow="Status da IA" title="Precedência automática" /><div className="v5-provider-stack"><ProviderRow name="IBM watsonx.ai" detail={aiStatus?.watsonx.model || "Motor principal quando configurado"} active={Boolean(aiStatus?.watsonx.configured)} /><ProviderRow name="Google Gemini" detail={`${aiStatus?.gemini.model || "gemini-3.1-flash-lite"} · embeddings ${aiStatus?.gemini.embeddingModel || "gemini-embedding-2"}`} active={Boolean(aiStatus?.gemini.configured)} experimental /><ProviderRow name="Fallback determinístico" detail="Memória, scores e ações transparentes" active /></div><div className="v5-quota"><span>Gemini generativo hoje<strong>{String(aiStatus?.gemini.usage?.generativeToday || 0)} / 450</strong></span><ProgressBar label="Uso generativo" hideLabel value={Number(aiStatus?.gemini.usage?.generativeToday || 0) / 4.5} /><span>Embeddings hoje<strong>{String(aiStatus?.gemini.usage?.embeddingsToday || 0)} / 900</strong></span><ProgressBar label="Uso embeddings" hideLabel value={Number(aiStatus?.gemini.usage?.embeddingsToday || 0) / 9} /></div></section><section className="v5-card"><CardHeader eyebrow="Política da conta" title={selected?.customerName || "Selecione uma conta"} /><div className="v5-settings-form"><Select id="account-classification" labelText="Classificação" value={classification} onChange={(event) => setClassification(event.target.value as Discovery["dataClassification"])} disabled={!privateMode}><SelectItem value="test" text="Teste — Gemini permitido" /><SelectItem value="confidential" text="Confidencial — Gemini bloqueado" /></Select><TextInput id="company-domain-setting" labelText="Domínio confirmado" value={domain} onChange={(event) => setDomain(event.target.value)} placeholder="empresa.com.br" disabled={!privateMode} /><Button size="sm" disabled={!privateMode || !selected} onClick={() => onSettings({ dataClassification: classification, companyDomain: domain })}>Salvar política</Button></div></section><section className="v5-card"><CardHeader eyebrow="Controles ativos" title="Governança por padrão" /><div className="v5-control-list">{["Autorização por conta no servidor", "Demo pública sem chamadas ao Gemini", "Fontes e confiança em toda recomendação", "Alterações e handoff somente com aprovação", "Cache, cota e circuit breaker", "Migrations aditivas e rollback V4"].map((item) => <div key={item}><Checkmark />{item}</div>)}</div></section><section className="v5-card"><CardHeader eyebrow="Integrações" title="Camada antes do CRM" /><div className="v5-provider-stack"><ProviderRow name="OpenAI Sites + D1 + R2" detail="Aplicação, estado e documentos" active /><ProviderRow name="Sign in with ChatGPT" detail="Workspace privado e ownership" active /><ProviderRow name="CRM" detail="Handoff preparado; escrita externa só na V6" active={false} /><ProviderRow name="Calendário, Teams e Slack" detail="Proatividade externa planejada para V6" active={false} /></div></section><section className="v5-card v5-span-2"><CardHeader eyebrow="Auditoria" title="Execuções recentes" /><div className="v5-audit-table">{data.aiRuns.slice(0, 12).map((run) => <article key={run.id}><span><strong>{run.agent}</strong><small>{run.detail}</small></span><em>{run.provider}{run.model ? ` · ${run.model}` : ""}</em><span><strong>{run.latencyMs || 0} ms</strong><small>{run.cached ? "cache" : `${run.promptTokens || 0} → ${run.outputTokens || 0} tokens`}</small></span><Tag type={run.status === "completed" ? "green" : "gray"}>{run.status}</Tag></article>)}</div></section></div></section>;
}

function CopilotPanel({ open, mode, setMode, selected, action, question, setQuestion, result, preparation, saving, onClose, onAsk, onPrepare, onNavigate, onDecision }: { open: boolean; mode: "ask" | "prepare" | "next"; setMode: (mode: "ask" | "prepare" | "next") => void; selected?: Discovery; action?: Action; question: string; setQuestion: (value: string) => void; result: ChatResult | null; preparation: Record<string, unknown> | null; saving: boolean; onClose: () => void; onAsk: (event?: FormEvent) => void; onPrepare: () => void; onNavigate: (sourceId: string) => void; onDecision: (action: Action, status: string, extras?: Record<string, unknown>) => void }) {
  return <aside className={`v5-copilot ${open ? "open" : ""}`} aria-hidden={!open}><header><div><span>Copiloto da conta</span><strong>{selected?.customerName || "Selecione uma conta"}</strong></div><button onClick={onClose} aria-label="Fechar"><Close /></button></header><nav>{[["ask", "Perguntar"], ["prepare", "Preparar conversa"], ["next", "Próximo passo"]].map(([id, label]) => <button key={id} className={mode === id ? "active" : ""} onClick={() => setMode(id as typeof mode)}>{label}</button>)}</nav><div className="v5-copilot-body"><InlineNotification kind="info" lowContrast title="Fundamentado na conta" subtitle="Separa fato, hipótese e inferência; nunca altera dados sozinho." hideCloseButton />{mode === "ask" && <>{result ? <div className="v5-answer"><header><Tag type={result.aiStatus === "gemini" ? "purple" : result.aiStatus === "watsonx" ? "blue" : "gray"}>{result.provider || result.aiStatus}{result.cached ? " · cache" : ""}</Tag><strong>{result.confidence}% confiança</strong></header><p>{result.answer}</p>{Boolean(result.facts?.length || result.hypotheses?.length || result.inferences?.length) && <Accordion align="start"><AccordionItem title="Fatos">{result.facts?.map((item) => <p key={item}>{item}</p>)}</AccordionItem><AccordionItem title="Hipóteses">{result.hypotheses?.map((item) => <p key={item}>{item}</p>)}</AccordionItem><AccordionItem title="Inferências">{result.inferences?.map((item) => <p key={item}>{item}</p>)}</AccordionItem></Accordion>}<div className="v5-citations">{result.citations.map((source, index) => <button key={`${source.sourceId}-${index}`} onClick={() => onNavigate(source.sourceId)}><span>{index + 1}</span><div><strong>{source.title}</strong><small>{source.excerpt}</small></div></button>)}</div></div> : <div className="v5-suggested">{questions.map((item) => <button key={item} onClick={() => setQuestion(item)}>{item}<ArrowRight /></button>)}</div>}<form className="v5-copilot-input" onSubmit={onAsk}><textarea value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Pergunte sobre evidências, pessoas ou próximos passos…" rows={3} /><button disabled={saving || !selected || !question.trim()} aria-label="Enviar"><ArrowRight /></button></form></>}{mode === "prepare" && <div className="v5-prepare"><label>Foco da conversa<textarea value={question} onChange={(event) => setQuestion(event.target.value)} placeholder={action?.conversation.theme || "Tema, pessoa ou objetivo"} rows={3} /></label><Button renderIcon={Calendar} disabled={saving || !selected} onClick={onPrepare}>{saving ? "Preparando…" : "Gerar briefing"}</Button>{preparation && <div className="v5-preparation"><Tag type={String(preparation.provider).includes("gemini") ? "purple" : String(preparation.provider).includes("watsonx") ? "blue" : "gray"}>{String(preparation.provider || "fallback")}</Tag><h3>{String(preparation.summary || preparation.objective || "Briefing da conversa")}</h3><List title="Perguntas" items={(preparation.nextQuestions || []) as string[]} /><List title="Riscos e objeções" items={(preparation.risks || []) as string[]} /><List title="Próximos passos" items={(preparation.nextActions || []) as string[]} /></div>}</div>}{mode === "next" && <div className="v5-next-step">{action ? <><div className="v5-score-orb">{action.priorityScore}</div><Tag type={statusTone(action.status)}>{statusLabel[action.status] || action.status}</Tag><h2>{action.title}</h2><p>{action.rationale}</p><dl><div><dt>Por que agora</dt><dd>{action.whyNow}</dd></div><div><dt>Resultado esperado</dt><dd>{action.expectedOutcome}</dd></div><div><dt>Prazo</dt><dd>{formatDate(action.dueAt)}</dd></div></dl><blockquote>{action.nextStep}</blockquote><div>{action.evidence.slice(0, 4).map((source) => <button key={source.sourceId} onClick={() => onNavigate(source.sourceId)}>{source.title}</button>)}</div>{action.status === "proposal" && <Button onClick={() => onDecision(action, "accepted")}>Aceitar recomendação</Button>}</> : <Empty text="Nenhuma ação recomendada para esta conta." />}</div>}</div></aside>;
}

function NewAccountModal({ open, saving, onClose, onSave }: { open: boolean; saving: boolean; onClose: () => void; onSave: (payload: Record<string, unknown>) => void }) { return <ComposedModal open={open} onClose={onClose} size="sm"><ModalHeader title="Nova conta" label="Workspace privado" /><ModalBody><form id="new-account-form" className="v5-form" onSubmit={(event) => { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); }}><TextInput id="new-company" name="customerName" labelText="Empresa" required /><TextInput id="new-industry" name="industry" labelText="Setor" required /><TextInput id="new-domain" name="companyDomain" labelText="Domínio (opcional)" placeholder="empresa.com.br" /><Select id="new-size" name="companySize" labelText="Porte" defaultValue="Enterprise"><SelectItem value="Enterprise" text="Enterprise" /><SelectItem value="Large" text="Large" /><SelectItem value="Mid-market" text="Mid-market" /></Select><Select id="new-classification" name="dataClassification" labelText="Classificação" defaultValue="test"><SelectItem value="test" text="Teste — Gemini permitido" /><SelectItem value="confidential" text="Confidencial — Gemini bloqueado" /></Select></form></ModalBody><ModalFooter><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" form="new-account-form" disabled={saving}>{saving ? "Criando…" : "Criar conta"}</Button></ModalFooter></ComposedModal>; }

function InformationModal({ open, saving, account, preview, onClose, onBack, onPreview, onConfirm }: { open: boolean; saving: boolean; account?: Discovery; preview: Record<string, unknown> | null; onClose: () => void; onBack: () => void; onPreview: (payload: Record<string, unknown>) => void; onConfirm: () => void }) { return <ComposedModal open={open} onClose={onClose} size="md"><ModalHeader title={preview ? "Revise antes de aplicar" : "Adicionar informação"} label={account?.customerName || "Conta"} /><ModalBody>{preview ? <div className="v5-preview"><InlineNotification kind="info" lowContrast title="Nenhuma alteração foi aplicada" subtitle="Confirme abaixo para atualizar memória, hipóteses e ações." hideCloseButton /><dl>{Object.entries(preview).filter(([key]) => !["requiresHumanConfirmation"].includes(key)).map(([key, value]) => <div key={key}><dt>{key.replaceAll(/([A-Z])/g, " $1")}</dt><dd>{Array.isArray(value) ? value.join(" · ") : String(value || "—")}</dd></div>)}</dl></div> : <form id="information-form" className="v5-form" onSubmit={(event) => { event.preventDefault(); onPreview(Object.fromEntries(new FormData(event.currentTarget).entries())); }}><Select id="info-kind" name="kind" labelText="Tipo" defaultValue="note"><SelectItem value="note" text="Anotação" /><SelectItem value="discovery_answer" text="Resposta de descoberta" /><SelectItem value="scheduled_meeting" text="Reunião futura" /><SelectItem value="initiative" text="Iniciativa" /><SelectItem value="system" text="Sistema" /><SelectItem value="pain" text="Dor" /><SelectItem value="risk" text="Risco" /><SelectItem value="objective" text="Objetivo" /><SelectItem value="commitment" text="Compromisso" /><SelectItem value="contradiction" text="Contradição" /></Select><TextInput id="info-title" name="title" labelText="Título" required placeholder="Resumo curto" /><TextArea id="info-content" name="content" labelText="Informação e fonte" rows={7} required placeholder="Descreva o que foi observado, quem disse e em qual contexto…" /><TextInput id="info-date" name="occurredAt" type="datetime-local" labelText="Data / prazo (opcional)" /><Select id="info-status" name="evidenceStatus" labelText="Natureza" defaultValue="confirmed"><SelectItem value="confirmed" text="Evidência confirmada" /><SelectItem value="assumption" text="Hipótese a validar" /><SelectItem value="gap" text="Lacuna" /><SelectItem value="stale" text="Desatualizada" /></Select></form>}</ModalBody><ModalFooter><Button kind="secondary" onClick={onClose}>Cancelar</Button>{preview ? <><Button kind="tertiary" onClick={onBack}>Revisar novamente</Button><Button disabled={saving} onClick={onConfirm}>{saving ? "Aplicando…" : "Confirmar e recalcular"}</Button></> : <Button type="submit" form="information-form" disabled={saving}>{saving ? "Analisando…" : "Visualizar impacto"}</Button>}</ModalFooter></ComposedModal>; }

function StakeholderModal({ open, account, stakeholder, people, saving, onClose, onSave }: { open: boolean; account?: Discovery; stakeholder: Stakeholder | null; people: Stakeholder[]; saving: boolean; onClose: () => void; onSave: (payload: Record<string, unknown>) => void }) { return <ComposedModal open={open} onClose={onClose} size="md"><ModalHeader title={stakeholder ? "Editar stakeholder" : "Adicionar stakeholder"} label={`Relacionamentos · ${account?.customerName || "Conta"}`} /><ModalBody><form id="stakeholder-form" className="v5-form two" onSubmit={(event) => { event.preventDefault(); onSave(Object.fromEntries(new FormData(event.currentTarget).entries())); }}><TextInput id="stakeholder-name" name="name" labelText="Nome" defaultValue={stakeholder?.name} required /><TextInput id="stakeholder-role" name="role" labelText="Cargo" defaultValue={stakeholder?.role} required /><TextInput id="stakeholder-area" name="area" labelText="Área" defaultValue={stakeholder?.area} /><Select id="stakeholder-manager" name="reportsToId" labelText="Reporta para" defaultValue={stakeholder?.reportsToId || ""}><SelectItem value="" text="Topo / não mapeado" />{people.filter((person) => person.id !== stakeholder?.id).map((person) => <SelectItem key={person.id} value={person.id} text={person.name} />)}</Select><Select id="stakeholder-influence" name="influence" labelText="Influência" defaultValue={stakeholder?.influence || "Média"}><SelectItem value="Alta" text="Alta" /><SelectItem value="Média" text="Média" /><SelectItem value="Baixa" text="Baixa" /></Select><Select id="stakeholder-stance" name="stance" labelText="Postura" defaultValue={stakeholder?.stance || "Desconhecido"}><SelectItem value="Aliado" text="Aliado" /><SelectItem value="Neutro" text="Neutro" /><SelectItem value="Resistente" text="Resistente" /><SelectItem value="Desconhecido" text="Desconhecido" /></Select><TextInput id="stakeholder-priorities" name="priorities" labelText="Prioridades" defaultValue={stakeholder?.priorities.join(", ")} /><TextArea id="stakeholder-notes" name="notes" labelText="Contexto e abordagem recomendada" rows={5} defaultValue={stakeholder?.notes} /></form></ModalBody><ModalFooter><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" form="stakeholder-form" disabled={saving}>Salvar stakeholder</Button></ModalFooter></ComposedModal>; }

function ActionModal({ open, action, saving, onClose, onSave }: { open: boolean; action: Action | null; saving: boolean; onClose: () => void; onSave: (payload: Record<string, unknown>) => void }) { return <ComposedModal open={open} onClose={onClose} size="sm"><ModalHeader title="Editar decisão" label={action?.title || "Next Best Action"} /><ModalBody><form id="action-form" className="v5-form" onSubmit={(event) => { event.preventDefault(); onSave({ ...Object.fromEntries(new FormData(event.currentTarget).entries()), edited: true }); }}><TextInput id="action-title" name="title" labelText="Ação" defaultValue={action?.title} /><TextArea id="action-next-step" name="nextStep" labelText="Próximo passo" defaultValue={action?.nextStep} rows={4} /><Select id="action-status" name="status" labelText="Decisão" defaultValue={action?.status || "proposal"}><SelectItem value="accepted" text="Aceitar" /><SelectItem value="in_progress" text="Em andamento" /><SelectItem value="snoozed" text="Adiar" /><SelectItem value="completed" text="Concluir" /><SelectItem value="discarded" text="Descartar" /></Select><TextInput id="action-date" name="snoozedUntil" type="date" labelText="Adiar até / novo prazo" /><TextArea id="action-reason" name="reason" labelText="Motivo ou feedback" rows={3} helperText="Obrigatório para descarte; usado apenas para ordenar melhor, sem treinar modelos." /></form></ModalBody><ModalFooter><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" form="action-form" disabled={saving}>Registrar decisão</Button></ModalFooter></ComposedModal>; }

function ResearchModal({ open, account, saving, onClose, onResearch }: { open: boolean; account?: Discovery; saving: boolean; onClose: () => void; onResearch: (payload: Record<string, unknown>) => void }) { return <ComposedModal open={open} onClose={onClose} size="sm"><ModalHeader title="Pesquisar sinais públicos" label="Google Search grounding · sob demanda" /><ModalBody><InlineNotification kind="warning" lowContrast title="Confirme a empresa" subtitle="Achados serão propostas citadas e não entrarão na memória sem aprovação." hideCloseButton /><form id="research-form" className="v5-form" onSubmit={(event) => { event.preventDefault(); onResearch({ ...Object.fromEntries(new FormData(event.currentTarget).entries()), confirmed: true }); }}><TextInput id="research-name" name="companyName" labelText="Nome exato" defaultValue={account?.customerName} required /><TextInput id="research-domain" name="domain" labelText="Domínio oficial" defaultValue={account?.companyDomain || ""} required placeholder="empresa.com.br" /><TextArea id="research-question" name="question" labelText="Foco da pesquisa" rows={4} defaultValue="Sinais estratégicos, tecnologia, investimentos e riscos recentes" /></form></ModalBody><ModalFooter><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" form="research-form" disabled={saving}>{saving ? "Pesquisando…" : "Confirmar e pesquisar"}</Button></ModalFooter></ComposedModal>; }

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <header className="v5-page-heading"><div><span>{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</header>; }
function CardHeader({ eyebrow, title, side }: { eyebrow: string; title: string; side?: ReactNode }) { return <header className="v5-card-head"><div><span>{eyebrow}</span><h2>{title}</h2></div>{side}</header>; }
function Empty({ text }: { text: string }) { return <div className="v5-empty"><span>◇</span><p>{text}</p></div>; }
function List({ title, items }: { title: string; items: string[] }) { return <div className="v5-list"><strong>{title}</strong>{items.length ? <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul> : <small>Sem informação suficiente.</small>}</div>; }
function MemoryColumn({ title, tone, items }: { title: string; tone: string; items: string[] }) { return <section className={tone}><header><i />{title}<em>{items.length}</em></header>{items.map((item) => <p key={item}>{item}</p>)}{!items.length && <small>Nenhum item nesta categoria.</small>}</section>; }
function MemoryMini({ title, count, tone, items }: { title: string; count: number; tone: string; items: string[] }) { return <article className={tone}><header><span>{title}</span><strong>{count}</strong></header><p>{items[0] || "Nenhum item nesta categoria."}</p></article>; }
function ProviderRow({ name, detail, active, experimental }: { name: string; detail: string; active: boolean; experimental?: boolean }) { return <article><i className={active ? "active" : "inactive"} /><span><strong>{name}</strong><small>{detail}</small></span><Tag type={active ? experimental ? "purple" : "green" : "gray"}>{active ? experimental ? "Experimental" : "Ativo" : "Planejado"}</Tag></article>; }
function MeetingForm({ onSave, saving, readonly }: { onSave: (payload: Record<string, unknown>) => void; saving: boolean; readonly: boolean }) { return <form className="v5-form compact" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSave({ title: form.get("title"), notes: form.get("notes"), attendees: form.get("attendees") }); }}><TextInput id="meeting-title" name="title" labelText="Título" defaultValue="Reunião de account intelligence" disabled={readonly} /><TextInput id="meeting-attendees" name="attendees" labelText="Participantes" placeholder="CFO, CIO, Ana Souza" disabled={readonly} /><TextArea id="meeting-notes" name="notes" labelText="Notas livres" required rows={7} placeholder="Contexto, falas, dores, sistemas, compromissos e dúvidas…" disabled={readonly} /><Button type="submit" disabled={saving || readonly}>{saving ? "Analisando…" : "Salvar e analisar"}</Button></form>; }

async function uploadDocument(file: File, accountId: string, mode: string, notify: (value: string) => void, reload: () => Promise<void>, setSaving: (value: boolean) => void) {
  if (file.size > 15 * 1024 * 1024) { notify("O arquivo excede o limite de 15 MB."); return; }
  setSaving(true);
  try {
    const extracted = await extractText(file); const form = new FormData(); form.append("file", file); form.append("extractedText", extracted.text); form.append("pagesJson", JSON.stringify(extracted.pages)); form.append("scope", mode);
    const response = await fetch(`/api/accounts/${accountId}/documents`, { method: "POST", body: form }); const payload = await response.json() as { error?: string };
    if (!response.ok) throw new Error(payload.error || "Falha no upload");
    await reload(); notify(extracted.text ? "Documento adicionado à memória com citações." : "Documento salvo; este PDF requer resumo manual.");
  } catch (error) { notify(error instanceof Error ? error.message : "Não foi possível processar o documento."); } finally { setSaving(false); }
}
async function extractText(file: File): Promise<{ text: string; pages: Array<{ page: number; text: string }> }> {
  const extension = file.name.split(".").pop()?.toLowerCase();
  if (extension === "txt" || extension === "md" || extension === "markdown") { const text = await file.text(); return { text, pages: [{ page: 1, text }] }; }
  if (extension === "docx") { const mammoth = await import("mammoth/mammoth.browser"); const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() }); return { text: result.value, pages: [{ page: 1, text: result.value }] }; }
  if (extension === "pdf") { const pdfjs = await import("pdfjs-dist"); pdfjs.GlobalWorkerOptions.workerSrc = new URL("pdfjs-dist/build/pdf.worker.min.mjs", import.meta.url).toString(); const pdf = await pdfjs.getDocument({ data: new Uint8Array(await file.arrayBuffer()) }).promise; const pages: Array<{ page: number; text: string }> = []; for (let index = 1; index <= pdf.numPages; index += 1) { const page = await pdf.getPage(index); const content = await page.getTextContent(); const text = content.items.map((item) => "str" in item ? item.str : "").join(" "); pages.push({ page: index, text }); } return { text: pages.map((page) => page.text).join("\n\n"), pages }; }
  throw new Error("Tipo de arquivo não suportado.");
}
